ROUTINES = "tasks.templates"
LEARNING = ["learning.view", "learning.manage"]


def give_learning(apps, schema_editor):
    AccessRole = apps.get_model("members", "AccessRole")
    for role in AccessRole.objects.filter(permissions__contains=[ROUTINES]):
        missing = [code for code in LEARNING if code not in role.permissions]
        if missing:
            role.permissions = [*role.permissions, *missing]
            role.save(update_fields=["permissions"])



